const DEFAULT_API = 'https://api.example.invalid/v1';

class BackendClient {
  constructor(options = {}) {
    this.secretKey = options.secretKey;
    this.apiUrl = options.apiUrl || DEFAULT_API;
  }
  async request(path, init = {}) {
    const { secretKey } = this;
    const res = await fetch(`${this.apiUrl}${path}`, {
      ...init,
      headers: { Authorization: `Bearer ${secretKey}`, 'Content-Type': 'application/json', ...init.headers },
    });
    if (!res.ok) throw new Error(`request failed: ${res.status}`);
    return res.json();
  }
  getUser(userId) {
    return this.request(`/users/${userId}`);
  }
}

function createClient(options) {
  return new BackendClient({ ...options, secretKey: options.secretKey });
}

module.exports = { BackendClient, createClient };

